#include <WiFiClientSecure.h>
#include <HTTPUpdate.h>

const char* firmwareUrl =
    "https://updates.example.org/esp32/stable.bin";
extern const char rootCa[];        // Define with the trusted CA PEM.
WiFiClientSecure tls;

void setup() {
  Serial.begin(115200);
  // Connect Wi-Fi and validate the signed update manifest first.
  tls.setCACert(rootCa);           // Keep certificate checks enabled.
  const auto result = httpUpdate.update(tls, firmwareUrl);
  if (result == HTTP_UPDATE_OK) {
    ESP.restart();
  } else if (result == HTTP_UPDATE_FAILED) {
    Serial.println(httpUpdate.getLastErrorString());
  } else {
    Serial.println("No update available");
  }
}

void loop() {}
